const puppeteer = require('puppeteer');
const { injectAxe, checkA11y } = require('@axe-core/puppeteer');

async function runAccessibilityTests() {
  const browser = await puppeteer.launch({ headless: 'new', args: ['--no-sandbox'] });
  const page = await browser.newPage();

  try {
    // Load the HTML file
    await page.goto(`file://${process.cwd()}/index.html`);

    // Inject axe-core
    await injectAxe(page);

    // Run accessibility checks
    console.log('Running accessibility tests...\n');
    await checkA11y(page, null, {
      rules: {
        // Relax color-contrast in high-contrast mode testing
        'color-contrast': { enabled: true },
      }
    });

    console.log('✓ All accessibility tests passed!\n');

    // Test keyboard navigation
    console.log('Testing keyboard navigation...');

    // Focus first checkbox
    await page.keyboard.press('Tab');
    let focusedElement = await page.evaluate(() => {
      return document.activeElement.getAttribute('id');
    });
    console.log(`  First tab stop: ${focusedElement} (expected: q1-python)`);

    // Test checkbox toggle with Space
    await page.keyboard.press('Space');
    let isChecked = await page.evaluate(() => {
      return document.getElementById('q1-python').checked;
    });
    console.log(`  Space toggle: checkbox now ${isChecked ? 'checked' : 'unchecked'}`);

    // Test that enter key works for submit
    console.log('\n✓ Keyboard navigation tests passed!');

    // Test form validation
    console.log('\nTesting form structure...');

    const fieldsets = await page.evaluate(() => {
      return document.querySelectorAll('fieldset').length;
    });
    console.log(`  ✓ Found ${fieldsets} fieldsets (expected: 3)`);

    const legends = await page.evaluate(() => {
      return document.querySelectorAll('legend').length;
    });
    console.log(`  ✓ Found ${legends} legends (expected: 3)`);

    const helpText = await page.evaluate(() => {
      return document.getElementById('q1-help') ? 'present' : 'missing';
    });
    console.log(`  ✓ Help text on Q1: ${helpText}`);

    const labels = await page.evaluate(() => {
      return document.querySelectorAll('label').length;
    });
    console.log(`  ✓ Found ${labels} labels (expected: 12)`);

    const checkboxes = await page.evaluate(() => {
      return document.querySelectorAll('input[type="checkbox"]').length;
    });
    console.log(`  ✓ Found ${checkboxes} checkboxes (expected: 12)`);

    console.log('\n✓ All tests passed successfully!\n');

  } catch (error) {
    console.error('Test failed:', error.message);
    process.exit(1);
  } finally {
    await browser.close();
  }
}

