async function validateHTML() {
  const fs = require('fs');
  const path = require('path');

  // Read the HTML file
  const htmlPath = path.join(__dirname, 'index.html');
  const html = fs.readFileSync(htmlPath, 'utf8');

  // Create validator with preset configuration
  const htmlvalidate = new HtmlValidate({
    extends: ['html-validate:recommended'],
    rules: {
      'no-style-tag': 'off', // Allow inline styles if used
      'no-script': 'off', // Allow script tags
      'aria-label-misuse': 'off',
    }
  });

  // Validate
  const report = await htmlvalidate.validate(html);

  if (report.valid) {
    console.log('✓ HTML is valid!\n');
  } else {
    console.log('✗ HTML validation issues found:\n');
    report.messages.forEach(msg => {
      console.log(`  Line ${msg.line}: ${msg.message}`);
    });
    process.exit(1);
  }

  // Manual accessibility checks
  console.log('Running manual accessibility checks...\n');

  // Check for fieldsets
  const fieldsetMatch = html.match(/<fieldset/g);
  const fieldsetCount = fieldsetMatch ? fieldsetMatch.length : 0;
  console.log(`  ✓ Fieldsets: ${fieldsetCount} (expected: 3)`);
  if (fieldsetCount !== 3) {
    console.log('    ⚠ Warning: Expected 3 fieldsets for question grouping');
  }

  // Check for legends
  const legendMatch = html.match(/<legend>/g);
  const legendCount = legendMatch ? legendMatch.length : 0;
  console.log(`  ✓ Legends: ${legendCount} (expected: 3)`);

  // Check for labels
  const labelMatch = html.match(/<label/g);
  const labelCount = labelMatch ? labelMatch.length : 0;
  console.log(`  ✓ Labels: ${labelCount} (expected: 12)`);

  // Check for checkboxes
  const checkboxMatch = html.match(/type="checkbox"/g);
  const checkboxCount = checkboxMatch ? checkboxMatch.length : 0;
  console.log(`  ✓ Checkboxes: ${checkboxCount} (expected: 12)`);

