const { JSDOM } = require('jsdom');
const fs = require('fs');
const path = require('path');
const axe = require('axe-core');

async function runA11yTests() {
  // Read the HTML file
  const htmlPath = path.join(__dirname, 'index.html');
  const htmlContent = fs.readFileSync(htmlPath, 'utf8');

  // Create a JSDOM instance
  const dom = new JSDOM(htmlContent, {
    url: 'file://' + htmlPath
  });

  // Inject axe-core into the DOM
  const axeScript = fs.readFileSync(require.resolve('axe-core/axe.min.js'), 'utf8');
  dom.window.eval(axeScript);

  // Run axe
  const results = await new Promise((resolve, reject) => {
    dom.window.axe.run((error, results) => {
      if (error) reject(error);
      else resolve(results);
    });
  });

  // Display results
  console.log('\n========================================');
  console.log('ACCESSIBILITY TEST RESULTS');
  console.log('========================================\n');

  if (results.violations.length > 0) {
    console.log(`❌ VIOLATIONS FOUND: ${results.violations.length}\n`);
    results.violations.forEach((violation, index) => {
      console.log(`${index + 1}. ${violation.id.toUpperCase()} (${violation.impact})`);
      console.log(`   Description: ${violation.description}`);
      console.log(`   Help: ${violation.help}`);
      console.log(`   Nodes affected: ${violation.nodes.length}`);
      violation.nodes.forEach((node, nodeIndex) => {
        console.log(`     ${nodeIndex + 1}. ${node.html.substring(0, 80)}`);
      });
      console.log();
    });
  } else {
    console.log('✓ No violations found!\n');
  }

  if (results.passes.length > 0) {
    console.log(`✓ PASSED CHECKS: ${results.passes.length}`);
    results.passes.slice(0, 10).forEach(pass => {
      console.log(`   ✓ ${pass.id}`);
    });
    if (results.passes.length > 10) {
      console.log(`   ... and ${results.passes.length - 10} more`);
    }
    console.log();
  }

  if (results.incomplete.length > 0) {
    console.log(`⚠ INCOMPLETE (manual review needed): ${results.incomplete.length}`);
    results.incomplete.forEach(item => {
      console.log(`   ⚠ ${item.id}: ${item.description}`);
    });
    console.log();
  }

  console.log('========================================\n');

  return {
    violations: results.violations,
    passes: results.passes,
    incomplete: results.incomplete
  };
}

runA11yTests().then(results => {
  if (results.violations.length > 0) {
    console.log('REMEDIATION REQUIRED');
    process.exit(1);
  } else {
    console.log('ALL TESTS PASSED!');
    process.exit(0);
  }
}).catch(err => {
  console.error('Test error:', err);
  process.exit(1);
});

