async function runTests() {
  const htmlPath = path.join(__dirname, 'index.html');
  const fileUrl = 'file://' + htmlPath;

  try {
    console.log('\n========================================');
    console.log('ACCESSIBILITY TEST RESULTS (Pa11y)');
