    const errors = results.issues.filter(i => i.type === 'error');
    const warnings = results.issues.filter(i => i.type === 'warning');
    const notices = results.issues.filter(i => i.type === 'notice');

    if (errors.length > 0) {
      console.log(`❌ ERRORS: ${errors.length}\n`);
      errors.forEach((issue, index) => {
        console.log(`${index + 1}. ${issue.code}`);
        console.log(`   Message: ${issue.message}`);
        console.log(`   Element: ${issue.element}`);
        console.log(`   Runner: ${issue.runner}`);
        console.log();
      });
    }

    if (warnings.length > 0) {
      console.log(`⚠ WARNINGS: ${warnings.length}\n`);
      warnings.forEach((issue, index) => {
        console.log(`${index + 1}. ${issue.code}`);
        console.log(`   Message: ${issue.message}`);
        console.log(`   Element: ${issue.element}`);
        console.log();
      });
    }

    if (notices.length > 0) {
      console.log(`ℹ NOTICES: ${notices.length}\n`);
      notices.slice(0, 5).forEach((issue, index) => {
        console.log(`${index + 1}. ${issue.code}`);
        console.log(`   Message: ${issue.message}`);
      });
      if (notices.length > 5) {
        console.log(`... and ${notices.length - 5} more notices`);
      }
      console.log();
    }

    console.log('========================================\n');

