const fs = require('fs');
const path = require('path');
const { JSDOM } = require('jsdom');

async function analyzeAccessibility() {
  const htmlPath = path.join(__dirname, 'index.html');
  const htmlContent = fs.readFileSync(htmlPath, 'utf8');
  const dom = new JSDOM(htmlContent);
  const document = dom.window.document;

  console.log('\n========================================');
  console.log('ACCESSIBILITY ANALYSIS');
  console.log('========================================\n');

  const issues = [];

  // Check 1: Image alt text
  const images = document.querySelectorAll('img');
  images.forEach(img => {
    if (!img.getAttribute('alt')) {
      issues.push({
        type: 'error',
        code: 'image-alt',
        message: `Image missing alt text: ${img.outerHTML.substring(0, 50)}`
      });
    }
  });

  // Check 2: Form labels
  const inputs = document.querySelectorAll('input, textarea, select');
  inputs.forEach(input => {
    const id = input.getAttribute('id');
    const label = document.querySelector(`label[for="${id}"]`);
    if (!label && !input.getAttribute('aria-label')) {
      issues.push({
        type: 'error',
        code: 'form-label',
        message: `Input without label: id="${id}" type="${input.type}"`
      });
    }
  });

  // Check 3: Heading hierarchy
  const headings = document.querySelectorAll('h1, h2, h3, h4, h5, h6');
  let lastLevel = 0;
  headings.forEach((h, idx) => {
    const level = parseInt(h.tagName[1]);
    if (idx > 0 && level > lastLevel + 1) {
      issues.push({
        type: 'warning',
        code: 'heading-level-skip',
        message: `Heading level skipped: ${h.tagName} after h${lastLevel}`
      });
    }
    lastLevel = level;
  });

  // Check 4: Landmark structure
  const main = document.querySelector('main');
  if (!main) {
    issues.push({
      type: 'error',
      code: 'landmark-main',
      message: 'Page missing <main> landmark'
    });
  }

  // Check 5: Page title
  const title = document.querySelector('title');
  if (!title || !title.textContent.trim()) {
    issues.push({
      type: 'error',
      code: 'page-title',
      message: 'Page missing title element'
    });
  }

  // Check 6: Form elements with proper ARIA
  const checkboxes = document.querySelectorAll('input[type="checkbox"]');
  checkboxes.forEach(cb => {
    const name = cb.getAttribute('name');
    const id = cb.getAttribute('id');
    if (!id) {
      issues.push({
        type: 'error',
        code: 'checkbox-id',
        message: `Checkbox without ID: name="${name}"`
      });
    }
  });

  // Check 7: Button text
  const buttons = document.querySelectorAll('button');
  buttons.forEach(btn => {
    const text = btn.textContent.trim();
    if (!text && !btn.getAttribute('aria-label')) {
      issues.push({
        type: 'error',
        code: 'button-text',
        message: `Button without accessible text: ${btn.outerHTML.substring(0, 50)}`
      });
    }
  });

  // Check 8: Color contrast is tested via CSS (visual check needed)

  // Check 9: Fieldset/Legend for form groups
  const fieldsets = document.querySelectorAll('fieldset');
  fieldsets.forEach(fs => {
    const legend = fs.querySelector('legend');
    if (!legend) {
      issues.push({
        type: 'error',
        code: 'fieldset-legend',
        message: 'Fieldset missing legend'
      });
    }
  });

  // Check 10: aria-describedby associations
  const elementsWithDescribedBy = document.querySelectorAll('[aria-describedby]');
  elementsWithDescribedBy.forEach(elem => {
    const descIds = elem.getAttribute('aria-describedby').split(' ');
    descIds.forEach(id => {
      if (!document.getElementById(id)) {
        issues.push({
          type: 'error',
          code: 'aria-describedby-reference',
          message: `aria-describedby references non-existent id: "${id}"`
        });
      }
    });
  });

  // Categorize issues
  const errors = issues.filter(i => i.type === 'error');
  const warnings = issues.filter(i => i.type === 'warning');

  if (errors.length === 0 && warnings.length === 0) {
    console.log('✓ No accessibility issues found!\n');
    console.log('PASSED CHECKS:');
    console.log('  ✓ All form inputs have labels');
    console.log('  ✓ Heading hierarchy is correct');
    console.log('  ✓ Main landmark present');
    console.log('  ✓ Page title present');
    console.log('  ✓ All checkboxes have IDs');
    console.log('  ✓ All buttons have accessible text');
    console.log('  ✓ All fieldsets have legends');
    console.log('  ✓ aria-describedby references valid');
    console.log();
  } else {
    if (errors.length > 0) {
      console.log(`❌ ERRORS: ${errors.length}\n`);
      errors.forEach((issue, index) => {
        console.log(`${index + 1}. [${issue.code}] ${issue.message}`);
      });
      console.log();
    }

    if (warnings.length > 0) {
      console.log(`⚠ WARNINGS: ${warnings.length}\n`);
      warnings.forEach((issue, index) => {
        console.log(`${index + 1}. [${issue.code}] ${issue.message}`);
      });
      console.log();
    }
  }

  console.log('========================================\n');

  return { errors, warnings, issues };
}

analyzeAccessibility().then(result => {
  if (result.errors.length > 0) {
    console.log('REAL ISSUES FOUND - REMEDIATION REQUIRED\n');
    process.exit(1);
  } else {
    console.log('NO ERRORS FOUND!\n');
    process.exit(0);
  }
}).catch(err => {
  console.error('Analysis error:', err);
  process.exit(1);
});

