    console.log('  ✓ Page title present');
    console.log('  ✓ All checkboxes have IDs');
    console.log('  ✓ All buttons have accessible text');
    console.log('  ✓ All fieldsets have legends');
    console.log('  ✓ aria-describedby references valid');
    console.log();
  } else {
    if (errors.length > 0) {
      console.log(`❌ ERRORS: ${errors.length}\n`);
      errors.forEach((issue, index) => {
        console.log(`${index + 1}. [${issue.code}] ${issue.message}`);
      });
      console.log();
