      console.log(`⚠ WARNINGS: ${warnings.length}\n`);
      warnings.forEach((issue, index) => {
        console.log(`${index + 1}. [${issue.code}] ${issue.message}`);
      });
      console.log();
    }
  }

  console.log('========================================\n');

  return { errors, warnings, issues };
