// Helper function to get selected checkbox values for a question
function getSelectedAnswers(questionName) {
  const checkboxes = document.querySelectorAll(`input[name="${questionName}"]:checked`);
  return Array.from(checkboxes).map(cb => cb.value);
}

// Display quiz results
function displayResults(userAnswers) {
  let html = '';
  let score = 0;
  const totalQuestions = 3;

  // Calculate score
  for (let i = 1; i <= 3; i++) {
    const questionName = `q${i}`;
    const userAns = userAnswers[questionName].sort().join(',');
    const correctAns = correctAnswers[questionName].sort().join(',');
    if (userAns === correctAns) {
