          ${isCorrect ? '✓' : '✗'} Question ${i}
        </span>
        <div class="result-answer">
          <strong>Your answer:</strong> ${userAnswersList.length > 0 ? userAnswersList.join(', ') : '(no selection)'}
        </div>
        <div class="result-answer">
          <strong>Correct answer:</strong> ${correctList.join(', ')}
        </div>
      </div>
    `;
  }

  resultsContent.innerHTML = html;
  resultsDiv.hidden = false;
  quizForm.hidden = true;

  // Scroll to results
  resultsDiv.scrollIntoView({ behavior: 'smooth' });
}

// Reset quiz
function resetQuiz() {
  quizForm.reset();
  quizForm.hidden = false;
  resultsDiv.hidden = true;
  resultsContent.innerHTML = '';

  // Focus on the first question
  document.querySelector('input[name="q1"]').focus();
}
